      "/api/contact/merge": {
        "post": {
          "tags": [
            "Contact"
          ],
          "summary": "Merge Duplicate Contacts",
          "description": "Merges two duplicate contacts within the authenticated user's organization.\n\nDuring the merge:\n\n- Nullable fields are merged into the primary contact.\n- Emails are reassigned.\n- Calls are reassigned.\n- Meetings are reassigned.\n- Deals are reassigned.\n- WhatsApp conversations are reassigned.\n- The duplicate contact is deleted.\n- An organization activity is created.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "primaryContactId",
                    "duplicateContactId"
                  ],
                  "properties": {
                    "primaryContactId": {
                      "type": "string",
                      "example": "cmf3m9v0v0001abc123xyz789"
                    },
                    "duplicateContactId": {
                      "type": "string",
                      "example": "cmf3m9v0v0002abc123xyz789"
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Duplicate contact merged successfully.",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "mergedContactId": {
                        "type": "string"
                      },
                      "message": {
                        "type": "string",
                        "example": "Duplicate contact merged successfully."
                      },
                      "contact": {
                        "type": "object"
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Invalid request."
            },
            "401": {
              "description": "Authentication required."
            },
            "403": {
              "description": "User does not have permission to merge contacts."
            },
            "404": {
              "description": "Contact not found."
            },
            "500": {
              "description": "Internal server error."
            }
          }
        }
      },
