      "/crm/search": {
        "get": {
          "tags": [
            "CRM"
          ],
          "summary": "Global search across CRM, Projects, Finance, Meetings, Tasks, Documents, and Calls",
          "description": "Performs a global search across multiple modules within the authenticated user's organization.\n\nSupported entities:\n- Leads (name, email, phone, company)\n- Deals (name)\n- Contacts (name, email, phone)\n- Companies (name)\n- Projects (name, description)\n- Invoices (client name)\n- Payments (Razorpay Order ID, Razorpay Payment ID)\n- Meetings (title, location)\n- Tasks (title, description)\n- Documents (file name)\n- Calls (notes, transcript)\n\nSupports filtering by entity type and paginated results.\n\nEvery result contains:\n- type (entity type)\n- data (entity object)\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "query",
              "name": "q",
              "required": true,
              "description": "Search keyword.",
              "schema": {
                "type": "string",
                "example": "john"
              }
            },
            {
              "in": "query",
              "name": "type",
              "required": false,
              "description": "Filter search by entity type.",
              "schema": {
                "type": "string",
                "enum": [
                  "lead",
                  "deal",
                  "contact",
                  "company",
                  "project",
                  "invoice",
                  "payment",
                  "meeting",
                  "task",
                  "document",
                  "call"
                ]
              }
            },
            {
              "in": "query",
              "name": "page",
              "required": false,
              "description": "Page number.",
              "schema": {
                "type": "integer",
                "default": 1,
                "minimum": 1
              }
            },
            {
              "in": "query",
              "name": "limit",
              "required": false,
              "description": "Number of results per page.",
              "schema": {
                "type": "integer",
                "default": 10,
                "minimum": 1,
                "maximum": 100
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Search completed successfully.",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "results": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "type": {
                              "type": "string",
                              "enum": [
                                "lead",
                                "deal",
                                "contact",
                                "company",
                                "project",
                                "invoice",
                                "payment",
                                "meeting",
                                "task",
                                "document",
                                "call"
                              ]
                            },
                            "data": {
                              "type": "object"
                            }
                          }
                        }
                      },
                      "facets": {
                        "type": "object",
                        "properties": {
                          "lead": {
                            "type": "integer"
                          },
                          "deal": {
                            "type": "integer"
                          },
                          "contact": {
                            "type": "integer"
                          },
                          "company": {
                            "type": "integer"
                          },
                          "project": {
                            "type": "integer"
                          },
                          "invoice": {
                            "type": "integer"
                          },
                          "payment": {
                            "type": "integer"
                          },
                          "meeting": {
                            "type": "integer"
                          },
                          "task": {
                            "type": "integer"
                          },
                          "document": {
                            "type": "integer"
                          },
                          "call": {
                            "type": "integer"
                          }
                        }
                      },
                      "pagination": {
                        "type": "object",
                        "properties": {
                          "page": {
                            "type": "integer"
                          },
                          "limit": {
                            "type": "integer"
                          },
                          "total": {
                            "type": "integer"
                          },
                          "hasNextPage": {
                            "type": "boolean"
                          }
                        }
                      }
                    }
                  },
                  "example": {
                    "results": [
                      {
                        "type": "lead",
                        "data": {
                          "id": "cms123",
                          "name": "John Doe"
                        }
                      },
                      {
                        "type": "task",
                        "data": {
                          "id": "cmt123",
                          "title": "Follow up with client"
                        }
                      },
                      {
                        "type": "document",
                        "data": {
                          "id": "cmd123",
                          "fileName": "proposal.pdf"
                        }
                      },
                      {
                        "type": "call",
                        "data": {
                          "id": "cmc123",
                          "notes": "Discussed pricing"
                        }
                      }
                    ],
                    "facets": {
                      "lead": 2,
                      "deal": 1,
                      "contact": 0,
                      "company": 1,
                      "project": 1,
                      "invoice": 0,
                      "payment": 1,
                      "meeting": 1,
                      "task": 2,
                      "document": 1,
                      "call": 3
                    },
                    "pagination": {
                      "page": 1,
                      "limit": 10,
                      "total": 13,
                      "hasNextPage": true
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Organization missing or query parameter is invalid.",
              "content": {
                "application/json": {
                  "example": {
                    "message": "Query is required"
                  }
                }
              }
            },
            "401": {
              "description": "Unauthorized."
            },
            "500": {
              "description": "Internal server error."
            }
          }
        }
      },
