      "/crm/communication-intelligence/{leadId}": {
        "get": {
          "tags": [
            "CRM"
          ],
          "summary": "Get cross-channel communication intelligence for a lead",
          "description": "Aggregates communication history (WhatsApp, Email, Calls, Meetings, internal notes,\nand tasks) from the last 60 days for the given lead and generates AI-derived\nintelligence: buying probability, risk indicators, recommended next action,\nsuggested follow-up date, pending commitments, and a communication summary.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "path",
              "name": "leadId",
              "required": true,
              "schema": {
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Communication intelligence payload",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "intent": {
                        "type": "string",
                        "enum": [
                          "HIGH_INTENT",
                          "EXPLORATORY",
                          "PRICE_SHOPPING",
                          "STALLED"
                        ]
                      },
                      "intentExplanation": {
                        "type": "string"
                      },
                      "mood": {
                        "type": "string",
                        "enum": [
                          "ENTHUSIASTIC",
                          "SATISFIED",
                          "NEUTRAL",
                          "FRUSTRATED",
                          "ANXIOUS"
                        ]
                      },
                      "moodDrivers": {
                        "type": "string"
                      },
                      "buyingProbability": {
                        "type": "number",
                        "description": "0-100 lead score / buying probability"
                      },
                      "probabilityFactors": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "urgency": {
                        "type": "string",
                        "enum": [
                          "CRITICAL",
                          "HIGH",
                          "MEDIUM",
                          "LOW"
                        ]
                      },
                      "urgencyTriggers": {
                        "type": "string"
                      },
                      "risk": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "riskLevel": {
                              "type": "string",
                              "enum": [
                                "HIGH",
                                "MEDIUM",
                                "LOW"
                              ]
                            },
                            "description": {
                              "type": "string"
                            },
                            "sourceChannel": {
                              "type": "string",
                              "enum": [
                                "CALL",
                                "WHATSAPP",
                                "EMAIL",
                                "MEETING"
                              ]
                            }
                          }
                        }
                      },
                      "keyDates": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "date": {
                              "type": "string"
                            },
                            "event": {
                              "type": "string"
                            },
                            "significance": {
                              "type": "string"
                            }
                          }
                        }
                      },
                      "objections": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "objection": {
                              "type": "string"
                            },
                            "channel": {
                              "type": "string",
                              "enum": [
                                "CALL",
                                "WHATSAPP",
                                "EMAIL"
                              ]
                            },
                            "status": {
                              "type": "string",
                              "enum": [
                                "UNRESOLVED",
                                "ADDRESSED"
                              ]
                            }
                          }
                        }
                      },
                      "missedOpportunities": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "description": {
                              "type": "string"
                            },
                            "detectedAt": {
                              "type": "string"
                            }
                          }
                        }
                      },
                      "nextBestAction": {
                        "type": "object",
                        "properties": {
                          "actionTitle": {
                            "type": "string"
                          },
                          "detailedRationale": {
                            "type": "string"
                          },
                          "recommendedChannel": {
                            "type": "string",
                            "enum": [
                              "CALL",
                              "WHATSAPP",
                              "EMAIL",
                              "MEETING"
                            ]
                          },
                          "priority": {
                            "type": "string",
                            "enum": [
                              "URGENT",
                              "NORMAL"
                            ]
                          }
                        }
                      },
                      "suggestedFollowUp": {
                        "type": "object",
                        "description": "Recommended date/timeframe for the next follow-up",
                        "properties": {
                          "date": {
                            "type": "string"
                          },
                          "reason": {
                            "type": "string"
                          }
                        }
                      },
                      "pendingCommitments": {
                        "type": "array",
                        "description": "Unanswered questions or outstanding commitments from either side",
                        "items": {
                          "type": "object",
                          "properties": {
                            "description": {
                              "type": "string"
                            },
                            "raisedBy": {
                              "type": "string",
                              "enum": [
                                "CLIENT",
                                "REP"
                              ]
                            },
                            "channel": {
                              "type": "string",
                              "enum": [
                                "CALL",
                                "WHATSAPP",
                                "EMAIL",
                                "MEETING"
                              ]
                            },
                            "detectedAt": {
                              "type": "string"
                            }
                          }
                        }
                      },
                      "summary": {
                        "type": "string",
                        "description": "Concise summary of the overall communication history and current relationship state"
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Organization missing or invalid leadId"
            },
            "404": {
              "description": "Lead not found"
            },
            "502": {
              "description": "Communication intelligence generation failed (AI service error)"
            }
          }
        }
      },
