      "/dashboard/briefing": {
        "get": {
          "tags": [
            "Dashboard"
          ],
          "summary": "AI morning briefing summary tailored by role, or a 7-day weekly rollup",
          "description": "By default returns the daily AI morning briefing (unchanged, backward compatible).\nPass `?weekly=true` to get a 7-day weekly rollup instead, which includes an\nadditional `kpis` object with deterministic (non-AI) numeric metrics:\nnew leads, leads assigned, deals created/won/lost, revenue generated,\nfollow-ups completed/pending, and per-user team performance.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "query",
              "name": "weekly",
              "schema": {
                "type": "string",
                "enum": [
                  "true"
                ]
              },
              "description": "If \"true\", returns the 7-day weekly briefing with KPIs instead of the daily briefing"
            }
          ],
          "responses": {
            "200": {
              "description": "Morning briefing (default), or weekly briefing + kpis if weekly=true",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "summary": {
                        "type": "string"
                      },
                      "keyAchievements": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "criticalRisks": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "strategicPriorities": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "kpis": {
                        "type": "object",
                        "description": "Only present when weekly=true",
                        "properties": {
                          "period": {
                            "type": "object",
                            "properties": {
                              "from": {
                                "type": "string"
                              },
                              "to": {
                                "type": "string"
                              },
                              "days": {
                                "type": "number"
                              }
                            }
                          },
                          "newLeads": {
                            "type": "number"
                          },
                          "leadsAssigned": {
                            "type": "number"
                          },
                          "dealsCreated": {
                            "type": "number"
                          },
                          "dealsWon": {
                            "type": "number"
                          },
                          "dealsLost": {
                            "type": "number"
                          },
                          "revenueGenerated": {
                            "type": "number"
                          },
                          "followUpsCompleted": {
                            "type": "number"
                          },
                          "pendingFollowUps": {
                            "type": "number"
                          },
                          "teamPerformance": {
                            "type": "array",
                            "items": {
                              "type": "object",
                              "properties": {
                                "userId": {
                                  "type": "string"
                                },
                                "name": {
                                  "type": "string"
                                },
                                "dealsWon": {
                                  "type": "number"
                                },
                                "leadsAssigned": {
                                  "type": "number"
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
