      "/integrations/hubspot/sync": {
        "post": {
          "tags": [
            "Integrations"
          ],
          "summary": "Trigger a HubSpot CRM contact sync",
          "description": "Fetches all contacts from a HubSpot CRM account using cursor-based\npagination, normalizes them into the internal lead format, and\nupserts them into the database with deduplication and partial\nfailure tolerance.\n\nRequires a valid OAuth2 credential set for HubSpot. The access\ntoken will be automatically refreshed if expired.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "credential"
                  ],
                  "properties": {
                    "credential": {
                      "type": "object",
                      "required": [
                        "authType",
                        "accessToken",
                        "refreshToken",
                        "tokenUrl",
                        "clientId",
                        "clientSecret",
                        "expiresAt"
                      ],
                      "properties": {
                        "authType": {
                          "type": "string",
                          "enum": [
                            "oauth2"
                          ],
                          "description": "Must be \"oauth2\""
                        },
                        "accessToken": {
                          "type": "string",
                          "description": "Current HubSpot access token"
                        },
                        "refreshToken": {
                          "type": "string",
                          "description": "Long-lived refresh token for token rotation"
                        },
                        "tokenUrl": {
                          "type": "string",
                          "format": "uri",
                          "example": "https://api.hubapi.com/oauth/v1/token",
                          "description": "HubSpot OAuth2 token endpoint"
                        },
                        "clientId": {
                          "type": "string",
                          "description": "HubSpot OAuth2 application client ID"
                        },
                        "clientSecret": {
                          "type": "string",
                          "description": "HubSpot OAuth2 application client secret"
                        },
                        "expiresAt": {
                          "type": "string",
                          "format": "date-time",
                          "description": "ISO 8601 timestamp when the access token expires"
                        },
                        "scopes": {
                          "type": "string",
                          "description": "Optional space-delimited OAuth2 scopes"
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Sync completed successfully",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "data": {
                        "type": "object",
                        "properties": {
                          "fetch": {
                            "type": "object",
                            "properties": {
                              "totalFetched": {
                                "type": "integer",
                                "example": 250
                              },
                              "pagesRequested": {
                                "type": "integer",
                                "example": 3
                              },
                              "fetchDurationMs": {
                                "type": "integer",
                                "example": 1842
                              },
                              "truncated": {
                                "type": "boolean",
                                "example": false
                              },
                              "truncationReason": {
                                "type": "string",
                                "nullable": true
                              }
                            }
                          },
                          "pipeline": {
                            "type": "object",
                            "properties": {
                              "totalReceived": {
                                "type": "integer",
                                "example": 250
                              },
                              "totalNormalized": {
                                "type": "integer",
                                "example": 248
                              },
                              "duplicatesRemoved": {
                                "type": "integer",
                                "example": 5
                              },
                              "totalCreated": {
                                "type": "integer",
                                "example": 200
                              },
                              "totalUpdated": {
                                "type": "integer",
                                "example": 43
                              },
                              "totalFailed": {
                                "type": "integer",
                                "example": 2
                              },
                              "errors": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "externalId": {
                                      "type": "string"
                                    },
                                    "message": {
                                      "type": "string"
                                    },
                                    "stage": {
                                      "type": "string",
                                      "enum": [
                                        "normalization",
                                        "validation",
                                        "upsert"
                                      ]
                                    }
                                  }
                                }
                              },
                              "batchesProcessed": {
                                "type": "integer",
                                "example": 5
                              },
                              "totalDurationMs": {
                                "type": "integer",
                                "example": 3250
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Invalid request body (credential validation failed)",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "401": {
              "description": "Missing or invalid authentication token",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "500": {
              "description": "Internal server error during sync",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            }
          }
        }
      },
