      "/leads/create-leads": {
        "post": {
          "tags": [
            "Leads"
          ],
          "summary": "Create a new lead with automatic assignment",
          "description": "Creates a new lead for the authenticated organization.\n\nIf no assignee is provided, the system automatically assigns\nthe lead using the configured Assignment Engine.\n\nDepending on the configured organization strategy,\nassignment may use:\n\n- AI Recommendation\n- Round Robin\n- Equal Distribution\n- Manual Assignment\n\nAssignment activity and assignment history are\nautomatically recorded.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "name"
                  ],
                  "properties": {
                    "name": {
                      "type": "string",
                      "example": "John Doe"
                    },
                    "phone": {
                      "type": "string",
                      "nullable": true,
                      "example": "9876543210"
                    },
                    "email": {
                      "type": "string",
                      "format": "email",
                      "nullable": true,
                      "example": "john@example.com"
                    },
                    "company": {
                      "type": "string",
                      "nullable": true,
                      "example": "ABC Pvt Ltd"
                    },
                    "designation": {
                      "type": "string",
                      "nullable": true,
                      "example": "Manager"
                    },
                    "city": {
                      "type": "string",
                      "nullable": true,
                      "example": "Hyderabad"
                    },
                    "state": {
                      "type": "string",
                      "nullable": true,
                      "example": "Telangana"
                    },
                    "country": {
                      "type": "string",
                      "nullable": true,
                      "example": "India"
                    },
                    "territory": {
                      "type": "string",
                      "nullable": true,
                      "example": "South"
                    },
                    "language": {
                      "type": "string",
                      "nullable": true,
                      "example": "English"
                    },
                    "pinCode": {
                      "type": "string",
                      "nullable": true,
                      "example": "500081"
                    },
                    "product": {
                      "type": "string",
                      "nullable": true,
                      "example": "CRM"
                    },
                    "budget": {
                      "type": "number",
                      "nullable": true,
                      "example": 50000
                    },
                    "source": {
                      "type": "string",
                      "nullable": true,
                      "example": "Website"
                    },
                    "status": {
                      "type": "string",
                      "example": "NEW"
                    },
                    "assignedToId": {
                      "type": "string",
                      "nullable": true,
                      "description": "If provided, the lead is assigned directly. Otherwise, the configured Assignment Engine automatically assigns the lead."
                    },
                    "tags": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "note": {
                      "type": "string",
                      "nullable": true
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "201": {
              "description": "Lead created successfully."
            },
            "400": {
              "description": "Validation error."
            },
            "401": {
              "description": "Unauthorized."
            },
            "403": {
              "description": "Forbidden."
            }
          }
        }
      },
