      "/leads/bulk-assign-by-rule": {
        "post": {
          "tags": [
            "Leads"
          ],
          "summary": "Bulk assign leads using the configured assignment rule",
          "description": "Distributes each selected lead to an assignee chosen by the active\nassignment rule (Round Robin, Equal Distribution, Country, Language,\nPin Code, etc.). Reuses the existing assignment rule engine.\n\nLeads that are already closed/converted (WON, LOST, DEAD) are skipped.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "ids"
                  ],
                  "properties": {
                    "ids": {
                      "type": "array",
                      "minItems": 1,
                      "maxItems": 500,
                      "items": {
                        "type": "string"
                      },
                      "example": [
                        "cmr7uaedn0005unvx7kfhtbrr",
                        "cmr7uaedn0005unvx7kfhtb11"
                      ]
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Leads assigned successfully using the assignment rule",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "affectedRows": {
                        "type": "integer",
                        "example": 2
                      },
                      "assigned": {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "leadId": {
                              "type": "string"
                            },
                            "assignedToId": {
                              "type": "string"
                            },
                            "assignmentRuleId": {
                              "type": "string"
                            },
                            "strategy": {
                              "type": "string"
                            }
                          }
                        }
                      },
                      "skipped": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "failed": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Validation error"
            },
            "403": {
              "description": "Permission denied"
            },
            "409": {
              "description": "No active assignment rule configured"
            }
          }
        }
      },
