      "/api/meetings/create": {
        "post": {
          "tags": [
            "Meetings"
          ],
          "summary": "Create a meeting, optionally generating a real provider join link",
          "description": "If `provider` is set to `google_meet`, a real Google Meet link is generated via\nthe Google Calendar API using the creator's connected Gmail/Google account\n(see POST /email/oauth/gmail/connect). If `zoom` or `teams`, a placeholder\njoin link is generated pending real Zoom/Teams OAuth integration.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "title",
                    "startTime",
                    "endTime"
                  ],
                  "properties": {
                    "title": {
                      "type": "string"
                    },
                    "startTime": {
                      "type": "string",
                      "format": "date-time"
                    },
                    "endTime": {
                      "type": "string",
                      "format": "date-time"
                    },
                    "attendees": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "location": {
                      "type": "string",
                      "nullable": true
                    },
                    "meetingLink": {
                      "type": "string",
                      "nullable": true,
                      "description": "Manual link, used if provider is omitted"
                    },
                    "provider": {
                      "type": "string",
                      "enum": [
                        "google_meet",
                        "zoom",
                        "teams"
                      ],
                      "description": "If set, a join link is auto-generated for this provider"
                    },
                    "leadId": {
                      "type": "string",
                      "nullable": true
                    },
                    "dealId": {
                      "type": "string",
                      "nullable": true
                    },
                    "contactId": {
                      "type": "string",
                      "nullable": true
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "201": {
              "description": "Meeting created. `providerLinkError` is present (non-null) if link generation failed but the meeting was still created."
            }
          }
        }
      },
