      "/payments/webhook": {
        "post": {
          "tags": [
            "Payments"
          ],
          "summary": "Handle Razorpay webhook",
          "description": "Razorpay calls this endpoint directly. Do not invoke it from Swagger UI because the X-Razorpay-Signature must be calculated by Razorpay over the exact raw request body.",
          "parameters": [
            {
              "in": "header",
              "name": "X-Razorpay-Signature",
              "required": true,
              "description": "HMAC SHA-256 signature generated by Razorpay using the webhook secret and the exact raw request body.",
              "schema": {
                "type": "string"
              }
            },
            {
              "in": "header",
              "name": "X-Razorpay-Event-Id",
              "required": false,
              "description": "Razorpay event ID used for duplicate-delivery protection.",
              "schema": {
                "type": "string"
              }
            }
          ],
          "requestBody": {
            "required": true,
            "description": "The complete, unmodified Razorpay webhook event body. The invoice ID is read from payload.payment.entity.notes.invoiceId.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object"
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Webhook processed successfully"
            },
            "400": {
              "description": "Missing signature or malformed webhook payload"
            },
            "401": {
              "description": "Invalid webhook signature"
            },
            "503": {
              "description": "Webhook secret is not configured"
            }
          }
        }
      },
