      "/integrations/{id}/sync/start": {
        "post": {
          "tags": [
            "Integrations"
          ],
          "summary": "Start an integration sync job",
          "description": "Enqueues a background sync job for the specified integration. The job\nis processed asynchronously by the BullMQ worker, which:\n\n1. Loads the integration config and credentials\n2. Fetches records from the external API via GenericRestConnector\n3. Applies transformation rules from the integration mapping\n4. Persists records via SyncPipelineService (batch upsert + dedup)\n5. Creates a SyncRun audit record with full result metadata\n\nThe endpoint returns immediately with a 202 Accepted status and a\n`jobId` that can be used to track progress via the sync logs.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "path",
              "name": "id",
              "required": true,
              "schema": {
                "type": "string"
              },
              "description": "The integration ID to sync"
            }
          ],
          "requestBody": {
            "required": false,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "entityType": {
                      "type": "string",
                      "default": "contacts",
                      "description": "The entity type to sync (e.g. \"contacts\", \"deals\", \"leads\").\nDefaults to \"contacts\" if not specified.\n"
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "202": {
              "description": "Sync job enqueued successfully",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "message": {
                        "type": "string",
                        "example": "Sync job enqueued"
                      },
                      "data": {
                        "type": "object",
                        "properties": {
                          "jobId": {
                            "type": "string",
                            "description": "BullMQ job ID for tracking",
                            "example": "integration-sync:abc123:1693500000000"
                          },
                          "integrationId": {
                            "type": "string",
                            "example": "clxyz123456"
                          },
                          "entityType": {
                            "type": "string",
                            "example": "contacts"
                          }
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Integration is disabled or not in ACTIVE status"
            },
            "401": {
              "description": "Unauthorized — missing or invalid bearer token"
            },
            "403": {
              "description": "Organization context required or integration does not belong to the organization"
            },
            "404": {
              "description": "Integration not found"
            }
          }
        }
      },
