      "/integrations/{id}/transform/preview": {
        "post": {
          "tags": [
            "Integrations"
          ],
          "summary": "Preview transformation rules on a sample value",
          "description": "Accepts a sample value and an ordered array of transformation rules,\nexecutes the rules sequentially through the runtime engine, and returns\nthe final transformed output together with a step-by-step execution\ntrace. Use this endpoint to let users preview field-level\ntransformations before saving them to a mapping configuration.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "path",
              "name": "id",
              "required": true,
              "schema": {
                "type": "string"
              },
              "description": "Integration ID"
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "sampleValue",
                    "rules"
                  ],
                  "properties": {
                    "sampleValue": {
                      "description": "The value to transform (typically a string)",
                      "example": "  Hello World  "
                    },
                    "rules": {
                      "type": "array",
                      "minItems": 1,
                      "description": "Ordered list of transformation rules to apply",
                      "items": {
                        "type": "object",
                        "required": [
                          "type"
                        ],
                        "properties": {
                          "type": {
                            "type": "string",
                            "enum": [
                              "UPPERCASE",
                              "LOWERCASE",
                              "TRIM",
                              "PARSE_DATE",
                              "DEFAULT_VALUE",
                              "REGEX_REPLACE"
                            ]
                          },
                          "params": {
                            "type": "object",
                            "description": "Rule-specific parameters. DEFAULT_VALUE requires `{ defaultValue: \"...\" }`. REGEX_REPLACE requires `{ pattern: \"...\", replacement: \"...\" }` and optionally `{ flags: \"gi\" }`.\n",
                            "additionalProperties": true
                          }
                        }
                      }
                    }
                  }
                },
                "examples": {
                  "trim-and-uppercase": {
                    "summary": "Trim then uppercase",
                    "value": {
                      "sampleValue": "  hello world  ",
                      "rules": [
                        {
                          "type": "TRIM"
                        },
                        {
                          "type": "UPPERCASE"
                        }
                      ]
                    }
                  },
                  "default-value": {
                    "summary": "Apply a default value",
                    "value": {
                      "sampleValue": "",
                      "rules": [
                        {
                          "type": "DEFAULT_VALUE",
                          "params": {
                            "defaultValue": "N/A"
                          }
                        }
                      ]
                    }
                  },
                  "regex-replace": {
                    "summary": "Regex replace digits",
                    "value": {
                      "sampleValue": "Order #12345",
                      "rules": [
                        {
                          "type": "REGEX_REPLACE",
                          "params": {
                            "pattern": "\\d+",
                            "replacement": "***"
                          }
                        }
                      ]
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Transformation preview completed",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "data": {
                        "type": "object",
                        "properties": {
                          "originalValue": {
                            "description": "The value before any rules were applied",
                            "example": "  hello world  "
                          },
                          "transformedValue": {
                            "description": "The final value after all rules",
                            "example": "HELLO WORLD"
                          },
                          "steps": {
                            "type": "array",
                            "items": {
                              "type": "object",
                              "properties": {
                                "ruleIndex": {
                                  "type": "integer",
                                  "example": 0
                                },
                                "ruleType": {
                                  "type": "string",
                                  "example": "TRIM"
                                },
                                "output": {
                                  "description": "Value after this rule",
                                  "example": "hello world"
                                },
                                "success": {
                                  "type": "boolean",
                                  "example": true
                                },
                                "error": {
                                  "type": "string",
                                  "nullable": true,
                                  "description": "Error message if the rule failed"
                                }
                              }
                            }
                          },
                          "appliedRulesCount": {
                            "type": "integer",
                            "example": 2
                          }
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Invalid request body",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "401": {
              "description": "Missing or invalid authentication token",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "403": {
              "description": "Organization context required",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            }
          }
        }
      },
