      "/workspace/pages": {
        "post": {
          "tags": [
            "Workspace"
          ],
          "summary": "Create a new workspace page",
          "description": "Creates a new page within the authenticated user's organization.\nOptionally nest under an existing page by supplying `parentId`.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "title"
                  ],
                  "properties": {
                    "title": {
                      "type": "string",
                      "example": "Sprint 42 Planning"
                    },
                    "icon": {
                      "type": "string",
                      "example": "📋"
                    },
                    "coverImage": {
                      "type": "string",
                      "format": "uri",
                      "example": "https://images.unsplash.com/photo-sprint42"
                    },
                    "parentId": {
                      "type": "string",
                      "description": "CUID of the parent page for nesting",
                      "example": "clxyz1234abcd"
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "201": {
              "description": "Page created successfully",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "data": {
                        "$ref": "#/components/schemas/WorkspacePage"
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Validation error",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "401": {
              "description": "Unauthorized"
            },
            "404": {
              "description": "Parent page not found"
            }
          }
        }
      },
