      "/workspace/tasks/bulk-update": {
        "post": {
          "tags": [
            "Workspace Tasks"
          ],
          "summary": "Bulk update selected tasks (1 to 20 tasks) in a single request with per-task reporting",
          "description": "Allows updating status, priority, assignee, due dates or related fields across multiple\nselected tasks in one single API request. Validates organization ownership, workspace context,\nand permissions server-side. Reports individual success/failure per requested task.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "taskIds"
                  ],
                  "properties": {
                    "taskIds": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      },
                      "minItems": 1,
                      "maxItems": 20,
                      "example": [
                        "task-1",
                        "task-2",
                        "task-3"
                      ]
                    },
                    "update": {
                      "type": "object",
                      "properties": {
                        "status": {
                          "type": "string",
                          "enum": [
                            "TODO",
                            "IN_PROGRESS",
                            "DONE"
                          ]
                        },
                        "priority": {
                          "type": "string",
                          "enum": [
                            "LOW",
                            "MEDIUM",
                            "HIGH"
                          ]
                        },
                        "assignedToId": {
                          "type": "string",
                          "nullable": true
                        },
                        "dueDate": {
                          "type": "string",
                          "format": "date-time"
                        }
                      }
                    },
                    "workspaceId": {
                      "type": "string"
                    }
                  }
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Bulk update summary with per-task results",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "data": {
                        "type": "object",
                        "properties": {
                          "totalRequested": {
                            "type": "integer",
                            "example": 3
                          },
                          "totalUpdated": {
                            "type": "integer",
                            "example": 2
                          },
                          "totalFailed": {
                            "type": "integer",
                            "example": 1
                          },
                          "results": {
                            "type": "array",
                            "items": {
                              "type": "object",
                              "properties": {
                                "taskId": {
                                  "type": "string",
                                  "example": "task-1"
                                },
                                "success": {
                                  "type": "boolean",
                                  "example": true
                                },
                                "error": {
                                  "type": "string",
                                  "nullable": true,
                                  "example": "Task does not belong to this organization or does not exist"
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Validation error or invalid task IDs"
            },
            "401": {
              "description": "Unauthorized"
            },
            "403": {
              "description": "Workspace mismatch or forbidden"
            }
          }
        }
      },
