      "/workspace/search": {
        "get": {
          "tags": [
            "Workspace Search"
          ],
          "summary": "Global workspace search",
          "description": "Performs a permission-filtered, case-insensitive search across\nWorkspace Pages (by title), Blocks (by JSON content), and\nDatabases (by name) within the authenticated user's organization.\n\nResults are grouped by entity type and support cursor-free\npage/limit pagination.  The user will only see entities they\nhave created or have an explicit `PagePermission` entry for.\n",
          "security": [
            {
              "bearerAuth": []
            }
          ],
          "parameters": [
            {
              "in": "query",
              "name": "q",
              "required": true,
              "schema": {
                "type": "string",
                "minLength": 1,
                "maxLength": 500
              },
              "description": "The search term (case-insensitive partial match)",
              "example": "Sprint Planning"
            },
            {
              "in": "query",
              "name": "page",
              "schema": {
                "type": "integer",
                "minimum": 1,
                "default": 1
              },
              "description": "1-based page number"
            },
            {
              "in": "query",
              "name": "limit",
              "schema": {
                "type": "integer",
                "minimum": 1,
                "maximum": 50,
                "default": 20
              },
              "description": "Maximum results per entity group"
            }
          ],
          "responses": {
            "200": {
              "description": "Search results grouped by entity type",
              "content": {
                "application/json": {
                  "schema": {
                    "type": "object",
                    "properties": {
                      "success": {
                        "type": "boolean",
                        "example": true
                      },
                      "data": {
                        "type": "object",
                        "properties": {
                          "query": {
                            "type": "string",
                            "example": "Sprint Planning"
                          },
                          "page": {
                            "type": "integer",
                            "example": 1
                          },
                          "limit": {
                            "type": "integer",
                            "example": 20
                          },
                          "results": {
                            "type": "object",
                            "properties": {
                              "pages": {
                                "type": "object",
                                "properties": {
                                  "items": {
                                    "type": "array",
                                    "items": {
                                      "$ref": "#/components/schemas/WorkspaceSearchResultItem"
                                    }
                                  },
                                  "total": {
                                    "type": "integer",
                                    "example": 3
                                  }
                                }
                              },
                              "blocks": {
                                "type": "object",
                                "properties": {
                                  "items": {
                                    "type": "array",
                                    "items": {
                                      "$ref": "#/components/schemas/WorkspaceSearchResultItem"
                                    }
                                  },
                                  "total": {
                                    "type": "integer",
                                    "example": 12
                                  }
                                }
                              },
                              "databases": {
                                "type": "object",
                                "properties": {
                                  "items": {
                                    "type": "array",
                                    "items": {
                                      "$ref": "#/components/schemas/WorkspaceSearchResultItem"
                                    }
                                  },
                                  "total": {
                                    "type": "integer",
                                    "example": 1
                                  }
                                }
                              }
                            }
                          },
                          "totalResults": {
                            "type": "integer",
                            "example": 16
                          }
                        }
                      }
                    }
                  }
                }
              }
            },
            "400": {
              "description": "Validation error (missing or invalid query parameter)",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/ErrorResponse"
                  }
                }
              }
            },
            "401": {
              "description": "Unauthorized — missing or invalid Bearer token"
            }
          }
        }
      },
